<!DOCTYPE html>
<html><body>
<p id="nome">Página da Empresa</p>
<button onclick="mudar()">Modificar texto</button>
<script>
    function mudar() {
        const elemento = document.getElementById("nome");
        elemento.style.fontWeight = "bold";
        elemento.style.fontStyle = "italic";
    }
</script>
</body></html>

